var t=`0840-masala-dosa`;var a=`world-0840`;var n=`IN`;var r=`south-asia`;var o=8;var s=1263;var d={en:`Masala Dosa`,ua:`Масала доса`};var l={en:`Masala Dosa is a India dish made with idli rice, urad dal, potato, yellow onion. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Масала доса, страва кухні країни Індія. Основні складники: рис для ідлі, урід дал, картопля, жовта цибуля. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var m=[{en:`Soak the listed rice, grains or noodles in clean water for about 480 minutes as appropriate, then drain; grind rice and urad for batter if required by this dish.`,ua:`Замочіть зазначені рис, крупи або локшину у чистій воді приблизно на 480 хвилин залежно від продукту, потім злийте; для тіста за потреби подрібніть рис і урад.`,t:[`rice-soaking`],m:480,i:[[`idli-rice`,320,`g`],[`urad-dal`,110,`g`],[`water`,900,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:15,i:[[`water`,280,`ml`],[`table-salt`,6,`g`]]},{en:`Ferment the blended rice-and-urad batter in a clean covered container until risen and bubbly; the duration depends on temperature and starter activity.`,ua:`Ферментуйте подрібнену рисово-урудову основу в чистій накритій посудині до підйому й бульбашок; тривалість залежить від температури й активності закваски.`,t:[`mixed-grain-fermentation`],m:720,i:[]},{en:`Cook the listed ingredients in simmering water for about 15 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 15 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:15,i:[[`potato`,430,`g`],[`water`,800,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`yellow-onion`,190,`g`],[`serrano-pepper`,2,`pcs`],[`mustard-seeds`,5,`g`],[`ground-turmeric`,3,`g`],[`ghee`,30,`g`]]},{en:`Spread a thin circle of fermented batter on a hot oiled griddle until crisp, place the cooked potato masala in the middle and fold.`,ua:`Розподіліть тонке коло ферментованого тіста на гарячій змащеній сковороді до хрусткості, викладіть картопляну масалу по центру й складіть.`,t:[`griddle-cooking`],m:20,i:[[`canola-oil`,25,`ml`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:4,i:[[`cilantro`,18,`g`]]}];var u={slug:t,id:a,country:`IN`,region:r,servings:8,minutes:s,title:d,text:l,steps:m};export{n as country,u as default,a as id,s as minutes,r as region,o as servings,t as slug,m as steps,l as text,d as title};